"note": "■ 共和政ローマ\n・前509年、エトルリア人の王を追放して共和政。元老院（貴族＝パトリキ）とコンスル（執政官2名）が中心、非常時は独裁官\n・身分闘争：重装歩兵として活躍した平民（プレブス）が権利を獲得 → 護民官・平民会 → 十二表法（前5世紀半ば）→ リキニウス・セクスティウス法（前367）→ ホルテンシウス法（前287）\n・前272年にイタリア半島を統一（分割統治）→ ポエニ戦争（前264〜前146）でカルタゴに勝利。シチリアが最初の属州\n■ 内乱の1世紀\n・属州からの安い穀物と長期の従軍で中小農民が没落、ラティフンディア（奴隷制大農場）が広がる\n・グラックス兄弟の改革失敗 → マリウス（平民派）とスラ（閥族派）の争い → 同盟市戦争・スパルタクスの反乱\n・第1回三頭政治（ポンペイウス・カエサル・クラッスス）→ カエサルの独裁と暗殺（前44）→ 第2回三頭政治 → アクティウムの海戦（前31）でオクタウィアヌスが勝利\n■ 帝政ローマ\n・前27年、オクタウィアヌスがアウグストゥスの称号 → 元首政（プリンキパトゥス）。「ローマの平和」約200年\n・五賢帝：ネルウァ、トラヤヌス（最大版図）、ハドリアヌス、アントニヌス=ピウス、マルクス=アウレリウス=アントニヌス\n・212年、カラカラ帝が全自由民に市民権\n・3世紀の危機：軍人皇帝時代、ゲルマン人・ササン朝の圧迫。コロヌスを使うコロナトゥスへ\n・ディオクレティアヌス帝：専制君主政（ドミナトゥス）、四帝分治制、キリスト教大迫害\n・コンスタンティヌス帝：ミラノ勅令（313）、ニケーア公会議（325）、コンスタンティノープル遷都（330）、ソリドゥス金貨\n・テオドシウス帝：キリスト教の国教化（392）、死後の395年に東西分裂 → 西ローマ帝国は476年に滅亡（オドアケル）\n■ キリスト教\n・イエスの刑死 → ペテロ・パウロの伝道。ネロ帝などの迫害、カタコンベ。『新約聖書』はコイネーで記述\n・公会議：ニケーア（325）アタナシウス派を正統・アリウス派を異端 → エフェソス（431）ネストリウス派を異端（のち唐で景教）\n・教父アウグスティヌス『神の国』\n■ ローマの文化\n・実用的文化：ローマ法（市民法→万民法、のち『ローマ法大全』）、コロッセウム、アッピア街道、水道橋、パンテオン\n・ウェルギリウス『アエネイス』、キケロ、リウィウス『ローマ建国史』、タキトゥス『ゲルマニア』、プルタルコス『対比列伝』、ストラボン『地理誌』、プリニウス『博物誌』、プトレマイオス（天動説）\n・ユリウス暦（カエサルが制定）",
