"note": "■ インダス文明とアーリヤ人\n・前2600年ごろからインダス文明：モエンジョ=ダーロ、ハラッパー。計画都市、インダス文字（未解読）\n・前1500年ごろアーリヤ人がパンジャーブ地方に進入（『リグ=ヴェーダ』）→ 前1000年ごろガンジス川流域へ、鉄器\n・ヴァルナ制（バラモン・クシャトリヤ・ヴァイシャ・シュードラ）＋ジャーティ → のちのカースト制度。バラモン教 → ウパニシャッド哲学\n■ 新しい宗教と統一国家\n・前6世紀ごろ、ガウタマ=シッダールタ（仏教）、ヴァルダマーナ（ジャイナ教）。クシャトリヤ・ヴァイシャが支持。マガダ国・コーサラ国\n・マウリヤ朝（前4世紀末、チャンドラグプタ、都パータリプトラ）→ アショーカ王：ダルマによる統治、仏典結集、スリランカに布教\n・クシャーナ朝（1世紀、都プルシャプラ）カニシカ王 → 大乗仏教（ナーガールジュナ）、ガンダーラ美術（ヘレニズムの影響）\n・南インドではサータヴァーハナ朝。季節風貿易でローマと交易（『エリュトゥラー海案内記』）\n■ グプタ朝とその後\n・グプタ朝（4世紀、チャンドラグプタ1世）→ チャンドラグプタ2世の最盛期、東晋の法顕が訪問\n・ヒンドゥー教が定着、『マヌ法典』。サンスクリット文学（カーリダーサ『シャクンタラー』、『マハーバーラタ』『ラーマーヤナ』）、ゼロの概念、アジャンター石窟寺院（グプタ様式）\n・エフタルの侵入で衰退 → ヴァルダナ朝（ハルシャ王、玄奘が訪問・ナーランダー僧院）\n・南インド：チョーラ朝が海上交易で栄え、宋に使節。ヒンドゥー教のバクティ運動\n■ 東南アジア\n・ドンソン文化（銅鼓）。インド化と中国との関係\n・扶南（港市オケオ）、チャンパー（中国名「林邑」）、真臘（カンボジア）→ アンコール朝：アンコール=ワット（スールヤヴァルマン2世）、アンコール=トム\n・シュリーヴィジャヤ（スマトラ、義浄が滞在）、シャイレンドラ朝（ジャワ、ボロブドゥール）\n・ビルマのパガン朝、タイのスコータイ朝（上座部仏教）、ベトナムの大越（李朝・陳朝、字喃＝チュノム）、ジャワのマジャパヒト王国",
