"note": "■ 中国文明の成立\n・黄河流域：仰韶文化（彩陶）→ 竜山文化（黒陶）。長江流域にも稲作の文化（河姆渡遺跡）\n■ 殷・周\n・殷：殷墟（河南省安陽）。甲骨文字による占いの神権政治、青銅器\n・周：殷を倒し鎬京に都。封建制（一族・功臣に封土を与え、宗法で結束）\n・前770年に洛邑へ遷都（東周）→ 春秋時代（覇者が「尊王攘夷」）→ 戦国時代（戦国の七雄）\n・鉄製農具と牛耕の普及、青銅貨幣（刀銭・布銭・蟻鼻銭・円銭）\n■ 諸子百家\n・儒家：孔子（仁、『論語』）・孟子（性善説、王道政治、易姓革命）・荀子（性悪説、礼）\n・道家：老子・荘子（無為自然）。墨家：墨子（兼愛・非攻）\n・法家：商鞅・韓非・李斯（法による統治）。ほか兵家（孫子）・縦横家（蘇秦・張儀）・陰陽家（鄒衍）\n■ 秦\n・商鞅の改革で強国化 → 秦王政が前221年に中国統一し始皇帝に\n・郡県制、度量衡・貨幣（半両銭）・文字の統一、焚書・坑儒、万里の長城（匈奴対策）\n・陳勝・呉広の乱（「王侯将相いずくんぞ種あらんや」）→ 項羽と劉邦の争い → 前206年に滅亡\n■ 前漢\n・劉邦（高祖）、都は長安。郡国制 → 呉楚七国の乱（前154）鎮圧で中央集権化\n・武帝：匈奴遠征（衛青・霍去病）、張騫を大月氏へ派遣、敦煌郡など河西4郡、南越を征服、衛氏朝鮮を滅ぼし楽浪郡など4郡\n・財政難 → 塩・鉄・酒の専売、均輸・平準、五銖銭。董仲舒の献策で儒学を官学化（五経博士）、官吏登用は郷挙里選\n■ 新・後漢\n・外戚の王莽が新を建てる（8年）、周を理想とした復古政策 → 赤眉の乱で滅亡\n・光武帝（劉秀）が後漢を建てる（25年）、都は洛陽。57年に倭の奴国の使者に印綬\n・班超が西域都護として活躍、部下の甘英を大秦（ローマ）に派遣。166年、大秦王安敦の使者が日南郡に到着\n・宦官と官僚の対立（党錮の禁）→ 黄巾の乱（184、太平道の張角）→ 220年に滅亡\n■ 漢代の文化\n・訓詁学（鄭玄）。司馬遷『史記』（紀伝体の祖）、班固『漢書』\n・蔡倫が製紙法を改良。仏教の伝来（1世紀ごろ）、太平道・五斗米道",
