"note": "■ 三国〜晋\n・魏（曹丕、洛陽）・蜀（劉備、成都）・呉（孫権、建業）の三国時代\n・魏の屯田制、九品中正（郷里の評判で官吏を推薦）→ 豪族が高官を独占し門閥貴族が成立（「上品に寒門なく、下品に勢族なし」）\n・司馬炎が晋（西晋）を建て、280年に呉を滅ぼして統一。占田・課田法\n・八王の乱 → 五胡（匈奴・羯・鮮卑・氐・羌）の進入 → 永嘉の乱で西晋滅亡（316）\n・江南で東晋（建康、司馬睿）。華北は五胡十六国時代\n■ 南北朝\n・北朝：鮮卑の拓跋氏が北魏を建て、太武帝が439年に華北統一\n・孝文帝：均田制・三長制、洛陽遷都と漢化政策 → 東魏・西魏 → 北斉・北周。府兵制は西魏で始まる\n・南朝：宋・斉・梁・陳（都は建康）。江南の開発が進む\n■ 魏晋南北朝の文化（六朝文化）\n・貴族文化。清談（竹林の七賢）、陶淵明、謝霊運、『文選』（昭明太子）、四六駢儷体\n・書の王羲之、画の顧愷之（「女史箴図」）\n・仏教：仏図澄・鳩摩羅什（仏典の漢訳）、法顕（インドへ）。雲崗・竜門の石窟寺院\n・道教：寇謙之が新天師道を開き、北魏で国教的地位に\n■ 隋\n・楊堅（文帝）が581年に建国、589年に陳を滅ぼして統一。均田制・租調庸制・府兵制、科挙を開始\n・煬帝：大運河を完成、高句麗遠征に失敗 → 各地の反乱で618年に滅亡\n■ 唐\n・李淵（高祖）が建国、李世民（太宗）の「貞観の治」\n・律令格式、三省（中書省・門下省・尚書省）六部、御史台。均田制・租調庸制・府兵制\n・高宗の時に最大領域、辺境に都護府を置いて羈縻政策\n・則天武后（国号を周に）→ 玄宗の「開元の治」\n・均田制・府兵制の崩壊 → 募兵制、節度使 → 安史の乱（755〜763）\n・780年、楊炎の献策で両税法（現住地で、資産に応じて夏・秋の2回）。塩の専売\n・黄巣の乱（875〜884）→ 907年、節度使の朱全忠が唐を滅ぼす\n■ 唐の文化と東アジア\n・長安は国際都市。景教・祆教（ゾロアスター教）・マニ教が伝来\n・孔穎達『五経正義』。詩の李白・杜甫・白居易、古文復興の韓愈・柳宗元、書の顔真卿、画の呉道玄、唐三彩\n・新羅（676年に朝鮮半島統一、骨品制、都は金城）、渤海（大祚栄、上京竜泉府）、日本（遣唐使）、吐蕃（ソンツェン=ガンポ）、南詔\n・周辺諸国の君主に官位を与えて君臣関係を結ぶ冊封体制",
