"title": "内陸アジアの遊牧民とオアシス世界",
"note": "■ 遊牧国家\n・騎馬遊牧民：馬に乗り家畜を追う機動力 → 強力な軍事国家を形成\n・スキタイ（前7世紀ごろ、黒海北岸）：騎馬文化と動物文様の金属工芸\n・匈奴：前3世紀末、冒頓単于がモンゴル高原を統一し、漢の高祖を破る（白登山）→ 武帝の攻撃で弱体化、東西・南北に分裂\n・鮮卑：2世紀にモンゴル高原を支配 → 華北に進出（北魏）\n・柔然（5世紀、君主が「可汗」を称する）、エフタル（中央アジア、グプタ朝を圧迫、ササン朝と突厥に滅ぼされる）\n■ トルコ系の国家とトルコ化\n・突厥（6世紀半ば）：柔然を倒して大帝国、突厥文字（オルホン碑文）。583年に東西に分裂 → 唐に服属・のち復興\n・ウイグル（744年）：安史の乱で唐を援助、マニ教を受容、ウイグル文字 → 840年にキルギスに敗れて四散\n・ウイグルの一部が西へ移り、タリム盆地のオアシス地帯のトルコ化が進む →「トルキスタン」\n・10世紀、カラハン朝がトルコ系最初のイスラーム王朝に\n■ オアシス世界\n・オアシス都市：亀茲（クチャ）、于闐（ホータン）、高昌（トゥルファン）、敦煌、サマルカンド\n・ソグド人：サマルカンドなどを拠点に東西の交易で活躍、ソグド文字はウイグル文字のもとに\n・東西交易路：草原の道・オアシスの道（絹の道）・海の道\n■ チベット・雲南\n・吐蕃（7世紀、ソンツェン=ガンポ、チベット文字、チベット仏教のもと）\n・南詔（雲南、8世紀）→ 大理",
