"note": "■ イスラームの成立\n・6世紀後半、ビザンツとササン朝の抗争で紅海ルートが活発化 → メッカが商業都市として繁栄\n・クライシュ族のムハンマドが610年ごろ唯一神アッラーの啓示を受ける\n・622年、メディナへ移住（ヒジュラ、イスラーム暦の元年）→ ウンマ（信徒の共同体）を建設 → 630年にメッカを征服、カーバ神殿を聖殿に\n・聖典『クルアーン（コーラン）』、六信五行。ユダヤ教徒・キリスト教徒は「啓典の民」\n■ 正統カリフ時代（632〜661）\n・アブー=バクル → ウマル → ウスマーン → アリー（選挙で選ばれたカリフ）\n・ジハードによる大征服：ニハーヴァンドの戦い（642）でササン朝を破る、ビザンツからシリア・エジプトを奪う\n・征服地の異教徒からジズヤ（人頭税）・ハラージュ（地租）を徴収。軍営都市（ミスル）\n■ ウマイヤ朝（661〜750）\n・ムアーウィヤが開く、都ダマスクス。カリフ位の世襲化\n・アリーとその子孫を正統とするシーア派 ⇔ 多数派のスンナ派\n・西ゴート王国を滅ぼす（711）が、トゥール・ポワティエ間の戦い（732）でフランク王国に敗れる\n・「アラブ帝国」：アラブ人の特権、改宗した非アラブ人（マワーリー）にもジズヤ → 不満\n■ アッバース朝（750〜1258）\n・アブー=アルアッバースが開く。2代マンスールが新都バグダードを建設、ハールーン=アッラシードの時代に最盛期\n・ムスリムならアラブ人以外もジズヤ免除、アラブ人にもハラージュ →「イスラーム帝国」\n・751年、タラス河畔の戦いで唐軍を破る → 製紙法が西方へ伝わる\n・宰相（ワズィール）を置く官僚制\n■ イスラーム文化\n・固有の学問：神学・法学（シャリーア）、ウラマー（学者）、マドラサ（学院）\n・外来の学問：「知恵の館」でギリシア語文献をアラビア語に翻訳\n・フワーリズミー（代数学）、イブン=シーナー（『医学典範』）、イブン=ルシュド（アリストテレス注釈）、ガザーリー（神秘主義を理論化）\n・歴史：タバリー、イブン=ハルドゥーン（『世界史序説』）。旅行記：イブン=バットゥータ『三大陸周遊記』\n・文学：『千夜一夜物語』、フィルドゥシー『シャー=ナーメ』、ウマル=ハイヤーム『ルバイヤート』\n・スーフィズム（神秘主義）、モスク・ミナレット・アラベスク",
