"note": "■ ゲルマン人の大移動\n・古ゲルマン社会：民会、カエサル『ガリア戦記』・タキトゥス『ゲルマニア』\n・375年、フン人に圧迫された西ゴート人がローマ領内に移動 → 大移動の始まり\n・西ゴート（イベリア半島）、東ゴート（イタリア、テオドリック）、ヴァンダル（北アフリカ）、ブルグンド、ランゴバルド（北イタリア）、アングロ=サクソン（ブリテン島、七王国）\n・フン人のアッティラ → カタラウヌムの戦い（451）で西ローマ・ゲルマン連合軍に敗れる\n■ フランク王国\n・クローヴィスがメロヴィング朝を開き、アタナシウス派に改宗（ローマ人貴族の支持）\n・宮宰カール=マルテルがトゥール・ポワティエ間の戦い（732）でウマイヤ朝軍を撃退\n・ピピンがカロリング朝を開く（751）→ ラヴェンナ地方を教皇に寄進（ピピンの寄進、教皇領の起源）\n・カール大帝：アヴァール人・ザクセン人を征服、ランゴバルド王国を滅ぼす。伯を置き巡察使で監督。800年、教皇レオ3世から西ローマ皇帝の帝冠 → 西欧世界の自立\n・カロリング=ルネサンス（アルクイン）\n・ヴェルダン条約（843）・メルセン条約（870）で3分割 → 東フランク（ドイツ）・西フランク（フランス）・イタリア\n・962年、東フランクのオットー1世が教皇から帝冠 → 神聖ローマ帝国。西フランクではカペー朝（987）\n■ 外部勢力の侵入\n・イスラーム勢力、マジャール人（レヒフェルトの戦いでオットー1世に敗れる）、ノルマン人（ヴァイキング）\n・ノルマン人：ノルマンディー公国（911）、ノルマン朝（1066、ノルマンディー公ウィリアムの征服）、両シチリア王国、ノヴゴロド国（リューリク）、キエフ公国\n■ 封建社会\n・封建的主従関係：主君が家臣に封土を与え、家臣は軍役で奉仕（双務的契約）。起源はローマの恩貸地制度とゲルマンの従士制度\n・荘園：領主直営地と農民保有地、三圃制。農奴は賦役・貢納、結婚税・死亡税、移動の自由なし。不輸不入権\n■ ローマ=カトリック教会\n・教皇グレゴリウス1世がゲルマン人への布教。修道院：ベネディクトゥスがモンテ=カッシーノ（「祈り、働け」）\n・726年、ビザンツ皇帝レオン3世の聖像禁止令 → 東西教会の対立 → 1054年に分離（ギリシア正教会）\n・教会の腐敗 → クリュニー修道院の改革運動 → 教皇グレゴリウス7世と皇帝ハインリヒ4世の叙任権闘争 → カノッサの屈辱（1077）→ ヴォルムス協約（1122）\n・インノケンティウス3世の時代に教皇権が絶頂（「教皇は太陽、皇帝は月」）\n■ ビザンツ帝国と東ヨーロッパ\n・ユスティニアヌス大帝：ヴァンダル王国・東ゴート王国を滅ぼす、『ローマ法大全』（トリボニアヌス）、ハギア=ソフィア聖堂、養蚕\n・7世紀以降、軍管区（テマ）制と屯田兵制 → のちプロノイア制。ギリシア語が公用語に\n・1453年、オスマン帝国に滅ぼされる\n・スラヴ人：ロシア（キエフ公国のウラディミル1世がギリシア正教に改宗）、セルビア人（正教）、ポーランド人・チェック人（カトリック）\n・非スラヴ系：ブルガール人、マジャール人（ハンガリー王国）\n・キリル文字（ギリシア文字から）",
