"short": "中世ヨーロッパ②",
"title": "中世ヨーロッパ②（十字軍・都市・封建社会の崩壊・中世文化）",
"note": "■ 西ヨーロッパの拡大と十字軍\n・11〜13世紀、重量有輪犂・三圃制などで農業生産が増加 → 人口増、開墾運動（シトー修道会）、エルベ川以東への東方植民、イベリア半島のレコンキスタ\n・セルジューク朝の圧迫 → ビザンツ皇帝の救援要請 → 教皇ウルバヌス2世がクレルモン宗教会議（1095）で十字軍を提唱\n・第1回（1096〜99）イェルサレム王国を建設 → 第3回（サラーフ=アッディーンと戦う、英リチャード1世・仏フィリップ2世・独フリードリヒ1世）→ 第4回（インノケンティウス3世が提唱、ヴェネツィア商人の要求でコンスタンティノープル占領、ラテン帝国）\n・結果：教皇権の衰退、諸侯・騎士の没落、国王権の伸長、東方貿易の発展、ビザンツ・イスラーム文化の流入\n■ 商業の復活と中世都市\n・地中海商業圏（ヴェネツィア・ジェノヴァ・ピサ：香辛料などの東方貿易）、北海・バルト海商業圏（リューベック・ハンブルク：海産物・木材・毛織物）、シャンパーニュの大市、フランドル（毛織物）\n・自治都市：北イタリアのコムーネ、ドイツの帝国都市（自由都市）。「都市の空気は（人を）自由にする」\n・都市同盟：ロンバルディア同盟、ハンザ同盟（盟主リューベック）\n・ギルド：商人ギルド → 同職ギルド（ツンフト闘争）。親方・職人・徒弟。フィレンツェのメディチ家、アウクスブルクのフッガー家\n■ 封建社会の崩壊\n・貨幣経済の浸透 → 賦役から貨幣地代へ、農奴解放。黒死病（14世紀半ば）で農民の地位向上\n・領主の反動 → ジャックリーの乱（1358、仏）・ワット=タイラーの乱（1381、英、ジョン=ボール「アダムが耕しイヴが紡いだとき…」）\n・イギリスでヨーマン（独立自営農民）が成長\n■ 教皇権の衰退\n・フィリップ4世が教皇ボニファティウス8世と対立 → アナーニ事件（1303）→ 教皇のバビロン捕囚（1309〜77、アヴィニョン）→ 教会大分裂（1378〜1417）\n・ウィクリフ（英、聖書を英訳）、フス（ベーメン）→ コンスタンツ公会議（1414〜18）で教会大分裂を収拾、フスを火刑 → フス戦争\n■ 各国の動き\n・イギリス：ジョン王が大憲章（マグナ=カルタ、1215）を認める → シモン=ド=モンフォールの反乱で議会の起源 → 模範議会（1295、エドワード1世）→ 二院制\n・フランス：フィリップ2世（ジョン王から領地を奪う）、ルイ9世（アルビジョワ派を制圧）、フィリップ4世が三部会（1302）\n・百年戦争（1339〜1453）：フランドルとギエンヌをめぐる争い、エドワード3世の王位継承権主張。クレシー・ポワティエでイギリス優勢 → ジャンヌ=ダルクがオルレアン解放、シャルル7世が勝利\n・イギリスではバラ戦争（1455〜85、ランカスター家とヨーク家）→ ヘンリ7世がテューダー朝を開く\n・スペイン：カスティリャとアラゴンが統合してスペイン王国（1479）→ 1492年グラナダ陥落。ポルトガル王国\n・ドイツ：イタリア政策で国内が分裂、大空位時代 → カール4世の金印勅書（1356）で7選帝侯。スイスの独立運動\n・イタリア：教皇党（ゲルフ）と皇帝党（ギベリン）。北欧ではカルマル同盟（1397）\n■ 中世ヨーロッパの文化\n・神学が中心、ラテン語。スコラ学：普遍論争（実在論のアンセルムス、唯名論のアベラール）、トマス=アクィナス『神学大全』で大成、ウィリアム=オブ=オッカム\n・12世紀ルネサンス：イスラームからギリシア古典がラテン語訳される（トレド）。ロジャー=ベーコン（経験重視）\n・大学：ボローニャ（法学）、パリ（神学）、サレルノ（医学）、オクスフォード、ケンブリッジ\n・建築：ロマネスク様式（ピサ大聖堂）→ ゴシック様式（ステンドグラス、尖塔：ケルン大聖堂・シャルトル大聖堂・ノートルダム大聖堂）\n・騎士道物語：『ローランの歌』『ニーベルンゲンの歌』『アーサー王物語』、吟遊詩人",
