"no": 12,
"short": "宋・モンゴル",
"title": "宋と北方民族・モンゴル帝国",
"note": "■ 五代十国と宋\n・唐滅亡後、華北に5王朝（後梁〜後周）、地方に10国。武断政治、貴族の没落\n・960年、趙匡胤（太祖）が宋（北宋）を建国、都は開封。文治主義、皇帝直属の禁軍\n・科挙の整備：殿試を加える → 官僚は形勢戸（地主）出身の士大夫\n・北方民族への対応：遼と澶淵の盟（1004、宋が兄・毎年銀と絹を贈る）、西夏とも和約 → 財政難\n・神宗が王安石を登用し新法（青苗法・市易法・均輸法・募役法・保甲法・保馬法）→ 旧法党（司馬光）との党争\n・金と結んで遼を滅ぼす → 金が開封を占領し上皇徽宗・皇帝欽宗を連行（靖康の変、1126〜27）\n・南宋：高宗、都は臨安（杭州）。主戦派の岳飛と和平派の秦檜 → 金と和議（淮河が国境）\n■ 北方民族の国家\n・遼（キタイ）：耶律阿保機（916）、燕雲十六州を獲得、二重統治体制（部族制と州県制）、契丹文字\n・西夏：タングート、李元昊、西夏文字\n・金：女真、完顔阿骨打（1115）、猛安・謀克、女真文字 → 遼の一族耶律大石は西遼（カラキタイ）を建てる\n■ 宋代の社会と文化\n・江南の開発：「蘇湖（江浙）熟すれば天下足る」、占城稲。商業の発達：行・作、草市・鎮。交子（北宋）・会子（南宋）の紙幣。市舶司（広州・泉州・明州）\n・景徳鎮の陶磁器（白磁・青磁）\n・儒学：周敦頤 → 朱熹（朱子）が朱子学を大成（大義名分論、四書）、陸九淵（心即理）\n・歴史：司馬光『資治通鑑』（編年体）、欧陽脩。文学：宋詞、蘇軾。画：院体画（徽宗）と文人画\n・三大発明：火薬・羅針盤・木版印刷の普及（活字も）\n■ モンゴル帝国\n・1206年、テムジンがクリルタイでチンギス=ハンに。千戸制。ホラズム=シャー朝・西夏を滅ぼす\n・オゴデイ：金を滅ぼす（1234）、都カラコルム。バトゥの西征 → ワールシュタットの戦い（1241）、キプチャク=ハン国\n・フラグの西征 → アッバース朝を滅ぼし（1258）イル=ハン国。チャガタイ=ハン国\n・フビライ：大都に遷都、国号を元に（1271）、南宋を滅ぼす（1276、崖山の戦い1279で滅亡）。日本・ベトナム・ジャワなどに遠征\n・元の統治：モンゴル人第一主義、色目人を財務官僚に、漢人・南人。駅伝制（ジャムチ）、交鈔（紙幣）、大運河の改修・海運\n・東西交流：プラノ=カルピニ、ルブルック、マルコ=ポーロ『世界の記述（東方見聞録）』、モンテ=コルヴィノ（大都で布教）、イブン=バットゥータ\n・文化：郭守敬の授時暦（→日本の貞享暦）、元曲（『西廂記』『琵琶記』）、パスパ文字、チベット仏教\n・紅巾の乱（1351、白蓮教）→ 1368年に明に追われ北へ（北元）",
