"short": "アジアの諸帝国",
"title": "ティムール朝・オスマン帝国・サファヴィー朝・ムガル帝国",
"note": "■ ティムール朝\n・1370年、ティムールが西チャガタイ=ハン国から自立、都サマルカンド。イル=ハン国の故地を併合\n・1402年、アンカラの戦いでオスマン帝国のバヤジット1世を捕らえる。明遠征の途中で病死\n・トルコ=イスラーム文化：ウルグ=ベク（天文台）、ミニアチュール（細密画）、チャガタイ=トルコ語文学\n・16世紀初め、ウズベク人に滅ぼされる\n■ オスマン帝国\n・13世紀末、オスマン1世がアナトリアで建国 → バルカン進出、アドリアノープル（エディルネ）に遷都\n・バヤジット1世：ニコポリスの戦い（1396）で十字軍に勝利 → アンカラの戦いで敗北\n・メフメト2世：1453年にコンスタンティノープルを攻略（ビザンツ帝国滅亡）→ イスタンブル\n・セリム1世：1517年にマムルーク朝を滅ぼし、メッカ・メディナの保護者に\n・スレイマン1世：モハーチの戦い（1526）、第1次ウィーン包囲（1529）、プレヴェザの海戦（1538）で地中海の制海権。法典の整備、建築家シナン（スレイマン=モスク）\n・統治：ティマール制（騎士に徴税権）、デヴシルメ（キリスト教徒子弟の徴用）→ イェニチェリ。非ムスリムの共同体ミッレト（宗教共同体）に自治。外国人にカピチュレーション（領事裁判権などの特権）\n・1571年、レパントの海戦でスペインなどに敗れる。1683年、第2次ウィーン包囲に失敗 → 1699年カルロヴィッツ条約でハンガリーを失う\n・「チューリップ時代」（18世紀前半）\n■ サファヴィー朝（1501〜1736）\n・イスマーイール1世がタブリーズで建国、シーア派（十二イマーム派）を国教。君主はシャー\n・アッバース1世：イスファハーンに遷都（「イスファハーンは世界の半分」）、イマームのモスク。ポルトガルからホルムズ島を奪回\n■ ムガル帝国（1526〜1858）\n・バーブル（ティムールの子孫）がパーニーパットの戦いでロディー朝を破る\n・アクバル：マンサブダール制、首都アグラ、ジズヤ廃止など宥和政策（ヒンドゥー教徒との融和）\n・シャー=ジャハーン：タージ=マハル。アウラングゼーブ：最大領域、ジズヤ復活 → ヒンドゥー勢力の反発（マラーター王国・シク教徒・ラージプート）\n・インド=イスラーム文化：ウルドゥー語、ムガル絵画、シク教（ナーナク）",
