"short": "大航海・ルネサンス・宗教改革",
"title": "大航海時代・ルネサンス・宗教改革",
"note": "■ アメリカ大陸の古代文明\n・トウモロコシ・ジャガイモの農耕。鉄器・車輪・馬はなし\n・オルメカ文明 → マヤ文明（ユカタン半島、マヤ文字、二十進法）→ テオティワカン文明 → アステカ王国（都テノチティトラン）\n・アンデス：インカ帝国（都クスコ、キープ＝結縄、駅伝制、マチュ=ピチュ）\n■ 大航海時代\n・背景：香辛料の需要、オスマン帝国の東地中海進出、レコンキスタ、羅針盤・地理知識、マルコ=ポーロ『世界の記述』、トスカネリの地球球体説\n・ポルトガル：エンリケ航海王子 → バルトロメウ=ディアス（喜望峰、1488）→ ヴァスコ=ダ=ガマ（カリカット、1498）→ ゴア（1510）・マラッカ（1511）・マカオ居住権（1557）\n・スペイン：イサベルの援助でコロンブス（サンサルバドル島、1492）、アメリゴ=ヴェスプッチが「新大陸」と主張、バルボア（太平洋）、マゼラン一行の世界周航（1519〜22）\n・トルデシリャス条約（1494）で境界線 → ブラジルはポルトガル領（カブラル）\n・征服者（コンキスタドール）：コルテスがアステカ王国、ピサロがインカ帝国を滅ぼす。エンコミエンダ制 → ラス=カサスが先住民の酷使を告発。ポトシ銀山\n・影響：商業革命（大西洋岸へ移動）、価格革命（銀の流入で物価上昇）、東ヨーロッパの再版農奴制（農場領主制、グーツヘルシャフト）\n■ ルネサンス\n・14世紀、イタリア（フィレンツェ）から。ヒューマニズム（人文主義）、メディチ家の保護\n・文学：ダンテ『神曲』（トスカナ語）、ペトラルカ、ボッカチオ『デカメロン』、マキァヴェリ『君主論』\n・美術：ジョット → ボッティチェリ「ヴィーナスの誕生」、レオナルド=ダ=ヴィンチ「最後の晩餐」「モナ=リザ」、ミケランジェロ「ダヴィデ像」「最後の審判」、ラファエロ（聖母子像）。ブルネレスキ（サンタ=マリア大聖堂のドーム）、ブラマンテ（サン=ピエトロ大聖堂）\n・北方：エラスムス『愚神礼賛』、トマス=モア『ユートピア』、ラブレー、モンテーニュ『エセー』、セルバンテス『ドン=キホーテ』、シェークスピア、ファン=アイク兄弟（油絵）、デューラー、ブリューゲル\n・科学技術：グーテンベルクの活版印刷、火器・羅針盤の改良、コペルニクス（地動説）、ガリレイ、ケプラー\n■ 宗教改革\n・1517年、ルターが「95か条の論題」で贖宥状の販売を批判（教皇レオ10世、サン=ピエトロ大聖堂の修築）。信仰義認説・聖書主義・万人司祭\n・ヴォルムス帝国議会で皇帝カール5世と対立 → ザクセン選帝侯の保護で聖書をドイツ語訳。ドイツ農民戦争（ミュンツァー）\n・アウクスブルクの和議（1555）：諸侯がカトリックかルター派かを選択（個人の信仰の自由ではない）。領邦教会制\n・スイス：ツヴィングリ（チューリヒ）、カルヴァン（ジュネーヴ、『キリスト教綱要』、予定説、長老制）→ 商工業者に広まる（ユグノー・ピューリタン・プレスビテリアン・ゴイセン）\n・イギリス：ヘンリ8世の首長法（1534）でイギリス国教会 → エリザベス1世の統一法（1559）で確立\n・対抗宗教改革：トリエント公会議（1545〜63）、イエズス会（イグナティウス=ロヨラ、フランシスコ=ザビエル）、禁書目録・宗教裁判、魔女狩り",
