"short": "主権国家と近世ヨーロッパ",
"title": "主権国家体制の形成と近世ヨーロッパ（16〜18世紀）",
"note": "■ 主権国家体制\n・イタリア戦争（1494〜1559、フランス対ハプスブルク家）を通じて主権国家体制が形成。常備軍と官僚制を備えた絶対王政、王権神授説（ボシュエ）、重商主義\n■ スペインとオランダ\n・カルロス1世（＝神聖ローマ皇帝カール5世）→ フェリペ2世：レパントの海戦（1571）、ポルトガル併合（1580）→「太陽の沈まぬ国」\n・オランダ独立戦争（1568〜）：ユトレヒト同盟（北部7州、1579）→ 独立宣言（1581）、総督オラニエ公ウィレム → ウェストファリア条約で国際的に承認\n・アムステルダムが世界商業・金融の中心に。東インド会社（1602）、アンボイナ事件（1623）\n■ イギリス\n・エリザベス1世：統一法、無敵艦隊（アルマダ）を撃破（1588）、東インド会社（1600）。第1次囲い込み、毛織物工業\n・ステュアート朝：ジェームズ1世・チャールズ1世の専制 → 権利の請願（1628）\n・ピューリタン革命：議会派（クロムウェル、鉄騎隊）が勝利、1649年に国王処刑 → 共和政。水平派を弾圧、アイルランド征服、航海法（1651）→ 英蘭戦争、護国卿として独裁\n・王政復古（1660、チャールズ2世）→ 審査法（1673）・人身保護法（1679）、トーリ党とホイッグ党\n・名誉革命（1688〜89）：ウィリアム3世・メアリ2世、権利の宣言 → 権利の章典（1689）\n・グレートブリテン王国（1707、スコットランド合同）→ ハノーヴァー朝のジョージ1世、ウォルポールのもとで責任内閣制（「王は君臨すれども統治せず」）\n■ フランス\n・ユグノー戦争（1562〜98）、サンバルテルミの虐殺 → アンリ4世がブルボン朝を開きナントの王令（1598）\n・ルイ13世（宰相リシュリュー、三部会を停止）→ ルイ14世（宰相マザラン → フロンドの乱 → 親政、財務総監コルベールの重商主義、ヴェルサイユ宮殿、ナントの王令廃止）\n・侵略戦争：スペイン継承戦争（1701〜13）→ ユトレヒト条約（ブルボン家のスペイン王位承認、イギリスがジブラルタルなどを獲得）\n■ 三十年戦争（1618〜48）\n・ベーメンの新教徒の反乱から → デンマーク、スウェーデン（グスタフ=アドルフ）、フランス（旧教国だが新教側で参戦）が介入。皇帝側の傭兵隊長ヴァレンシュタイン\n・ウェストファリア条約（1648）：ドイツ諸侯の主権がほぼ認められ帝国は形骸化、スイス・オランダの独立承認、フランスはアルザス、スウェーデンは西ポンメルン\n■ 東ヨーロッパの大国\n・プロイセン：フリードリヒ=ヴィルヘルム1世（軍隊強化）→ フリードリヒ2世（大王、啓蒙専制君主「君主は国家第一の僕」、サンスーシ宮殿）。ユンカー\n・オーストリア：マリア=テレジア → オーストリア継承戦争（1740〜48、シュレジエンを失う）→ 外交革命（フランスと同盟）→ 七年戦争（1756〜63）でも奪回できず。ヨーゼフ2世の啓蒙改革\n・ロシア：イヴァン3世（モスクワ大公国、キプチャク=ハン国から自立）→ イヴァン4世（ツァーリの称号）→ ロマノフ朝（1613）→ ステンカ=ラージンの反乱 → ピョートル1世（大帝）：西欧化、北方戦争でスウェーデンのカール12世を破りバルト海進出、ペテルブルク建設 → エカチェリーナ2世：プガチョフの乱、ラクスマンを日本へ、クリミア半島獲得\n・ポーランド分割（1772・93・95、ロシア・プロイセン・オーストリア）、コシューシコの抵抗\n■ 植民地争奪と商業\n・英仏の植民地戦争：ファルツ・スペイン継承・オーストリア継承・七年戦争と並行して北米で戦う → フレンチ=インディアン戦争、インドでプラッシーの戦い（1757）→ パリ条約（1763）でイギリスの優位確定\n・大西洋三角貿易（武器・雑貨 → 奴隷 → 砂糖・綿花・タバコ）\n■ 17〜18世紀の文化\n・科学革命：ニュートン（万有引力）、ボイル、ハーヴェー（血液循環）、リンネ、ラヴォワジェ（質量保存）、ジェンナー（種痘）\n・哲学：ベーコン（経験論・帰納法）、デカルト（合理論・演繹法「我思う、ゆえに我あり」）、パスカル、スピノザ、ライプニッツ、カント\n・政治思想：グロティウス（国際法の祖『戦争と平和の法』）、ホッブズ『リヴァイアサン』、ロック『統治二論』（抵抗権）\n・啓蒙思想：モンテスキュー『法の精神』（三権分立）、ヴォルテール、ルソー『社会契約論』、ディドロ・ダランベール『百科全書』\n・経済学：ケネー（重農主義）、アダム=スミス『諸国民の富』（自由放任）\n・美術：バロック（ルーベンス、レンブラント、ベラスケス、ヴェルサイユ宮殿）→ ロココ（サンスーシ宮殿、ワトー）\n・文学：ミルトン『失楽園』、バンヤン、デフォー、スウィフト、コルネイユ・ラシーヌ・モリエール\n・コーヒーハウス・サロンで世論が形成",
