"title": "産業革命と環大西洋革命",
"note": "■ イギリス産業革命\n・条件：資本の蓄積、第2次囲い込み（議会主導、農業革命・ノーフォーク農法）で労働力、植民地市場、石炭・鉄\n・綿工業から：ジョン=ケイの飛び杼 → ハーグリーヴズの多軸紡績機（ジェニー紡績機）→ アークライトの水力紡績機 → クロンプトンのミュール紡績機 → カートライトの力織機。ホイットニーの綿繰り機（アメリカ）\n・ワットが蒸気機関を改良 → 動力に。ダービーのコークス製鉄法\n・交通革命：スティーヴンソンの蒸気機関車（1825年ストックトン・ダーリントン間、1830年リヴァプール・マンチェスター間）、フルトンの蒸気船\n・影響：「世界の工場」、資本主義体制、工業都市（マンチェスター・バーミンガム）、労働問題 → ラダイト運動、工場法、労働組合、社会主義（オーウェン）\n■ アメリカ独立革命\n・13植民地（ヴァージニアが最初、ピルグリム=ファーザーズ）、植民地議会\n・七年戦争後の課税強化：印紙法（1765）→「代表なくして課税なし」→ 茶法 → ボストン茶会事件（1773）→ 大陸会議\n・レキシントン・コンコードの戦い（1775）、総司令官ワシントン。トマス=ペイン『コモン=センス』\n・独立宣言（1776年7月4日、ジェファソン起草、ロックの思想）\n・フランス・スペインの参戦、ロシアのエカチェリーナ2世による武装中立同盟。ヨークタウンの戦い（1781）→ パリ条約（1783）でミシシッピ川以東を獲得\n・合衆国憲法（1787）：連邦主義・三権分立・人民主権。初代大統領ワシントン。連邦派と反連邦派\n■ フランス革命\n・旧制度（アンシャン=レジーム）：第一身分（聖職者）・第二身分（貴族）が特権、第三身分。シエイエス『第三身分とは何か』\n・財政難 → 三部会（1789）→ 国民議会、球戯場（テニスコート）の誓い → バスティーユ牢獄襲撃（7月14日）→ 封建的特権の廃止・人権宣言（ラ=ファイエット）→ ヴェルサイユ行進\n・ヴァレンヌ逃亡事件（1791）→ 1791年憲法（立憲君主政）→ 立法議会（フイヤン派 vs ジロンド派）、オーストリアに宣戦 → 8月10日事件で王権停止\n・国民公会（1792）：共和政（第一共和政）、ルイ16世処刑（1793）→ 第1回対仏大同盟（ピット）→ ジャコバン派（山岳派）の恐怖政治（ロベスピエール、公安委員会、最高価格令、封建地代の無償廃止、革命暦、メートル法）\n・テルミドールの反動（1794）→ 総裁政府（1795）、バブーフの陰謀\n■ ナポレオン\n・イタリア遠征・エジプト遠征（ロゼッタ・ストーン）→ ブリュメール18日のクーデタ（1799）で統領政府\n・宗教協約（コンコルダート、1801）、アミアンの和約（1802）、ナポレオン法典（民法典、1804）→ 国民投票で皇帝ナポレオン1世（1804）\n・トラファルガーの海戦（1805、ネルソン）で敗北 → アウステルリッツの戦い（三帝会戦）→ ライン同盟（神聖ローマ帝国消滅、1806）→ 大陸封鎖令（ベルリン勅令、1806）→ ティルジット条約（ワルシャワ大公国）\n・プロイセン改革（シュタイン・ハルデンベルク、フィヒテ「ドイツ国民に告ぐ」）、スペイン反乱（ゴヤ「1808年5月3日」）\n・ロシア遠征失敗（1812）→ ライプツィヒの戦い（諸国民戦争、1813）→ エルバ島に流刑 → 百日天下 → ワーテルローの戦い（1815）→ セントヘレナ島\n■ ラテンアメリカの独立\n・クリオーリョ（植民地生まれの白人）が中心。ハイチ（トゥサン=ルヴェルチュール、1804年独立、初の黒人共和国）\n・シモン=ボリバル（ベネズエラ・コロンビア・ボリビアなど）、サン=マルティン（アルゼンチン・チリ・ペルー）、メキシコ（イダルゴ神父）、ブラジル（ポルトガル王子が帝位）\n・モンロー宣言（1823）、イギリス外相カニングの支持",
