"note": "■ ウィーン体制\n・ウィーン会議（1814〜15）：メッテルニヒが議長、タレーランの正統主義、勢力均衡。神聖同盟（アレクサンドル1世）・四国同盟（のち五国同盟）\n・自由主義・ナショナリズムの抑圧：ブルシェンシャフト、カルボナリ、デカブリストの乱（1825）→ ギリシア独立（1829〜30、ロンドン会議で承認）\n・七月革命（1830、シャルル10世 → ルイ=フィリップの七月王政）→ ベルギー独立、ポーランド反乱\n・二月革命（1848）→ 第二共和政、国立作業場、六月蜂起 → 「諸国民の春」：三月革命（ウィーンでメッテルニヒ失脚、ベルリン）、フランクフルト国民議会（大ドイツ主義と小ドイツ主義）、ハンガリー（コシュート）、ベーメン → ウィーン体制崩壊\n■ イギリスの自由主義改革\n・審査法廃止（1828）、カトリック教徒解放法（1829、オコンネル）\n・第1回選挙法改正（1832、腐敗選挙区の廃止、産業資本家に選挙権）→ チャーティスト運動（人民憲章）\n・穀物法廃止（1846、コブデン・ブライト）、航海法廃止（1849）→ 自由貿易体制\n・ヴィクトリア女王の時代：ロンドン万国博覧会（1851）。保守党ディズレーリと自由党グラッドストンの二大政党。第2回（1867）・第3回（1884）選挙法改正、教育法、労働組合法。アイルランド自治法案は否決\n■ フランス\n・ルイ=ナポレオンが大統領 → クーデタ → 国民投票で皇帝ナポレオン3世（第二帝政、1852）\n・クリミア戦争、アロー戦争、インドシナ出兵、メキシコ出兵失敗 → プロイセン=フランス戦争で捕虜に（1870）\n・臨時政府 → パリ=コミューン（1871）→ 第三共和政。ブーランジェ事件、ドレフュス事件\n■ イタリアとドイツの統一\n・イタリア：マッツィーニ（青年イタリア、ローマ共和国）→ サルデーニャ王国のヴィットーリオ=エマヌエーレ2世と首相カヴール（クリミア戦争参戦、プロンビエール密約）→ イタリア統一戦争でロンバルディア獲得、中部併合（サヴォイア・ニースをフランスに割譲）→ ガリバルディ（赤シャツ隊）が両シチリア王国を征服し献上 → イタリア王国（1861）→ ヴェネツィア併合（1866）・教皇領併合（1870）。「未回収のイタリア」が残る\n・ドイツ：ドイツ関税同盟（1834）→ ヴィルヘルム1世と首相ビスマルクの鉄血政策 → デンマーク戦争（1864）→ プロイセン=オーストリア戦争（1866）→ 北ドイツ連邦 → プロイセン=フランス戦争（1870〜71）→ ドイツ帝国（1871、ヴェルサイユ宮殿で皇帝即位）。フランスからアルザス・ロレーヌ獲得\n・ビスマルク：文化闘争（カトリック）、社会主義者鎮圧法と社会保険制度（アメとムチ）、ベルリン会議（1878）、三帝同盟・三国同盟（1882）・再保障条約でフランスを孤立させる\n・オーストリア=ハンガリー帝国（1867、アウスグライヒ）\n■ ロシアと東方問題\n・南下政策：エジプト=トルコ戦争 → クリミア戦争（1853〜56、ナイティンゲール）→ パリ条約で黒海中立化\n・アレクサンドル2世：農奴解放令（1861）→ ポーランド反乱 → 反動化。ナロードニキ（「ヴ=ナロード」）→ テロリズム、皇帝暗殺（1881）\n・ロシア=トルコ戦争（1877〜78）→ サン=ステファノ条約（ブルガリア自治国）→ ベルリン会議・ベルリン条約（ルーマニア・セルビア・モンテネグロ独立、オーストリアがボスニア・ヘルツェゴヴィナの行政権、イギリスがキプロス）\n■ アメリカ合衆国の発展\n・領土拡大：ルイジアナ購入（1803、フランスから）、フロリダ（スペインから）、テキサス併合、アメリカ=メキシコ戦争でカリフォルニア獲得（1848）→ ゴールドラッシュ。「明白な天命」\n・ジャクソン大統領：ジャクソニアン=デモクラシー、先住民強制移住法（「涙の旅路」）\n・南北対立（北部：保護貿易・奴隷制反対、南部：自由貿易・奴隷制）：ミズーリ協定（1820）→ カンザス・ネブラスカ法（1854）→ 共和党結成。ストウ『アンクル=トムの小屋』\n・リンカン大統領 → 南部11州がアメリカ連合国（デイヴィス）→ 南北戦争（1861〜65）、ホームステッド法、奴隷解放宣言（1863）、ゲティスバーグの戦い（「人民の、人民による、人民のための政治」）\n・戦後：シェアクロッパー、大陸横断鉄道（1869）、フロンティア消滅（1890年ごろ）、移民の増加\n■ 19世紀の文化\n・文学：古典主義（ゲーテ、シラー）→ ロマン主義（ハイネ、バイロン、ユゴー『レ=ミゼラブル』、グリム兄弟）→ 写実主義・自然主義（バルザック、フロベール、ディケンズ、ドストエフスキー、トルストイ、ゾラ、イプセン）\n・美術：ダヴィド（古典主義）、ドラクロワ「民衆を導く自由の女神」（ロマン主義）、ミレー（自然主義）、クールベ（写実主義）、印象派（モネ・ルノワール）、後期印象派（セザンヌ・ゴッホ・ゴーガン）、彫刻ロダン\n・音楽：ベートーヴェン、ショパン、ワグナー\n・哲学：カント → ヘーゲル（弁証法）、マルクス・エンゲルス『共産党宣言』（1848）・『資本論』、功利主義（ベンサム「最大多数の最大幸福」、J.S.ミル）、実証主義（コント）、ニーチェ\n・経済学：マルサス『人口論』、リカード、リスト（保護貿易）\n・科学：ダーウィン『種の起源』、メンデル、パストゥール、コッホ、ファラデー、レントゲン、キュリー夫妻、ノーベル。ランケ（近代歴史学）\n・社会主義：オーウェン、サン=シモン、フーリエ、プルードン。第1インターナショナル（1864）、第2インターナショナル（1889）",
