"note": "■ オスマン帝国と西アジア\n・ワッハーブ王国（アラビア半島、イスラーム改革のワッハーブ派とサウード家）\n・エジプト：ナポレオン撤退後、ムハンマド=アリーが総督に → 近代化、2度のエジプト=トルコ戦争でシリア領有を要求 → ロンドン会議（1840）でエジプト・スーダンの総督世襲権のみ\n・スエズ運河（1869、フランス人レセップス）→ 財政難で株をイギリスが買収（ディズレーリ）→ ウラービー運動（「エジプト人のためのエジプト」）→ イギリスが事実上保護国化（1882）\n・オスマン帝国：マフムート2世がイェニチェリ廃止 → タンジマート（1839、アブデュルメジト1世のギュルハネ勅令）→ ミドハト憲法（1876、ミドハト=パシャ）→ ロシア=トルコ戦争を口実にアブデュルハミト2世が停止、パン=イスラーム主義\n・イラン：ガージャール朝。トルコマンチャーイ条約（1828、ロシアに治外法権など）→ バーブ教徒の反乱 → タバコ=ボイコット運動（1891、アフガーニーの影響）\n■ 南アジアの植民地化\n・カーナティック戦争・プラッシーの戦い（1757）→ ベンガル・ビハール・オリッサのディーワーニー（徴税権）獲得（1765）\n・マイソール戦争・マラーター戦争・シク戦争で全インドを支配\n・徴税：ザミンダーリー制（ベンガル、地主に納税）、ライヤットワーリー制（南インド、農民に直接）\n・東インド会社の貿易独占権廃止（1813インド、1833全面停止で商業活動を終える）→ イギリスの綿製品流入でインドの綿織物業が打撃\n・インド大反乱（1857〜59、シパーヒーの反乱）→ ムガル帝国滅亡（1858）、東インド会社解散 → 直接統治 → インド帝国（1877、ヴィクトリア女王が皇帝）\n■ 東南アジアの植民地化\n・オランダ：ジャワ戦争 → 強制栽培制度（1830〜、総督ファン=デン=ボス、コーヒー・サトウキビなど）→ オランダ領東インド\n・イギリス：ペナン・マラッカ・シンガポール（ラッフルズ）→ 海峡植民地（1826）→ マレー連合州、錫・ゴム。ビルマ戦争（3回）でビルマをインド帝国に併合（1886）\n・フランス：阮朝（1802、阮福暎＝嘉隆帝、国号越南）→ 仏越戦争 → 劉永福の黒旗軍が抵抗 → 清仏戦争（1884〜85）・天津条約で清が宗主権放棄 → フランス領インドシナ連邦（1887、のちラオス編入）\n・スペイン：フィリピン、マニラ。タイ：ラタナコーシン（チャクリ）朝のラーマ4世・ラーマ5世（チュラロンコン）の近代化、英仏の緩衝地帯として独立維持\n■ 東アジアの開港\n・イギリスの対清貿易：マカートニー、アマーストの交渉失敗 → 三角貿易（インド産アヘンを清へ）→ 銀の流出\n・林則徐がアヘンを没収 → アヘン戦争（1840〜42）→ 南京条約（香港島割譲、上海など5港開港、公行廃止）→ 虎門寨追加条約（領事裁判権、関税自主権の喪失、片務的最恵国待遇）、望厦条約（米）・黄埔条約（仏）\n・アロー戦争（1856〜60、英仏）→ 天津条約 → 北京条約（天津など開港、九竜半島南部の割譲、外国公使の北京駐在、キリスト教布教の自由）。ロシアはアイグン条約（1858、黒竜江以北）・北京条約（沿海州）でウラジヴォストーク建設\n・太平天国（1851〜64）：洪秀全（上帝会）、「滅満興漢」、天朝田畝制度、南京（天京）を都 → 曽国藩の湘軍・李鴻章の淮軍、ゴードンの常勝軍が鎮圧\n・洋務運動（「中体西用」、同治中興）\n・朝鮮：大院君の鎖国攘夷 → 江華島事件 → 日朝修好条規（1876）→ 壬午軍乱・甲申政変（金玉均）→ 甲午農民戦争（東学）→ 日清戦争（1894〜95）→ 下関条約（朝鮮の独立承認、遼東半島・台湾・澎湖諸島の割譲、賠償金）→ 三国干渉\n・日本：日米和親条約（1854）・日米修好通商条約（1858）→ 明治維新",
