"note": "■ 第2次産業革命と帝国主義\n・19世紀後半、石油・電力を動力とする重化学工業 → 独占資本（カルテル・トラスト・コンツェルン）、金融資本 → 資本輸出・植民地獲得\n・イギリス：ジョゼフ=チェンバレン（植民相）、自治領（カナダ・オーストラリア・ニュージーランド・南アフリカ連邦）、労働党（1906）。アイルランド自治法（1914、実施延期）\n・フランス：第三共和政、ロシアと露仏同盟（1891〜94）\n・ドイツ：ヴィルヘルム2世の「世界政策」、社会民主党、3B政策\n・アメリカ：独占の進行、マッキンリー大統領のアメリカ=スペイン戦争（1898）→ フィリピン・グアム・プエルトリコ獲得、キューバを保護国化、ハワイ併合。ジョン=ヘイの門戸開放宣言。セオドア=ローズヴェルトの棍棒外交・パナマ運河、タフトのドル外交、ウィルソンの宣教師外交\n・ロシア：露仏同盟、シベリア鉄道、日露戦争中の血の日曜日事件（1905）→ 第1次ロシア革命、ニコライ2世の十月宣言、ドゥーマ、首相ストルイピン\n■ アフリカ分割\n・リヴィングストン・スタンリーの探検 → ベルリン会議（ベルリン=コンゴ会議、1884〜85、先占権）、コンゴ自由国（ベルギー王レオポルド2世）\n・イギリス：エジプト → スーダン（マフディー派の抵抗）、ケープ植民地 → セシル=ローズ、南アフリカ戦争（ブール戦争、1899〜1902）→ 縦断政策（3C政策：カイロ・ケープタウン・カルカッタ）\n・フランス：アルジェリア → チュニジア → サハラ → 横断政策 → ファショダ事件（1898）→ 英仏協商（1904）\n・ドイツ：モロッコ事件（1905タンジール・1911アガディール）→ フランスがモロッコ保護国化。イタリア：エチオピア侵入失敗（アドワの戦い1896）→ イタリア=トルコ戦争でリビア\n・独立を保ったのはエチオピアとリベリア\n■ 太平洋・ラテンアメリカ\n・オーストラリア（先住民アボリジニー）、ニュージーランド（マオリ人）。ドイツはビスマルク諸島など\n・メキシコ革命（1910、マデロ・サパタ・ディアス政権打倒）。アメリカのパン=アメリカ会議\n■ 列強の二極化\n・三国同盟（独・墺・伊）⇔ 露仏同盟 → 英仏協商（1904）→ 英露協商（1907）→ 三国協商\n・日英同盟（1902）→ 日露戦争（1904〜05）→ ポーツマス条約\n■ 中国の変革\n・中国分割：ドイツが膠州湾、ロシアが遼東半島（旅順・大連）、イギリスが威海衛・九竜半島（新界）、フランスが広州湾を租借\n・変法運動：康有為・梁啓超、光緒帝の戊戌の変法（1898）→ 西太后らの戊戌の政変\n・義和団事件（1900、「扶清滅洋」）→ 8か国共同出兵 → 北京議定書（辛丑和約、1901、北京駐兵権・巨額の賠償金）\n・光緒新政：科挙廃止（1905）、憲法大綱\n・革命運動：孫文が興中会 → 中国同盟会（1905、東京、三民主義＝民族・民権・民生）\n・鉄道国有化 → 四川暴動 → 武昌蜂起（1911）→ 辛亥革命 → 中華民国（1912、臨時大総統孫文、南京）→ 宣統帝（溥儀）退位 → 袁世凱が臨時大総統 → 第二革命・第三革命、帝政失敗 → 軍閥割拠\n・モンゴルが独立宣言、チベットも独立を主張\n■ アジアの民族運動\n・インド：インド国民会議（1885）→ ベンガル分割令（1905）→ カルカッタ大会（ティラク、英貨排斥・スワデーシ・スワラージ・民族教育の4綱領）→ 全インド=ムスリム連盟（1906）\n・イラン立憲革命（1905〜11）→ ロシアの干渉で挫折\n・オスマン帝国：青年トルコ革命（1908、ミドハト憲法の復活）\n・東南アジア：フィリピン（ホセ=リサール、アギナルドがフィリピン共和国を宣言→アメリカ=フィリピン戦争）、インドネシア（サレカット=イスラーム）、ベトナム（ファン=ボイ=チャウ、維新会、ドンズー運動）\n・日本：韓国併合（1910）、朝鮮総督府。義兵闘争、安重根による伊藤博文暗殺",
