"note": "■ 第一次世界大戦\n・バルカン問題：パン=ゲルマン主義とパン=スラヴ主義、オーストリアのボスニア・ヘルツェゴヴィナ併合（1908）、バルカン同盟 → バルカン戦争（1912・13）→「ヨーロッパの火薬庫」\n・サライェヴォ事件（1914年6月）→ 同盟国（独・墺・トルコ・ブルガリア）vs 協商国（英・仏・露、のちイタリア・日本・アメリカ）\n・西部戦線：マルヌの戦い → 塹壕戦、ヴェルダン・ソンムの戦い。東部戦線：タンネンベルクの戦い\n・新兵器（戦車・飛行機・毒ガス・潜水艦）、総力戦\n・イタリアはロンドン条約（1915）で協商国側に。日本は二十一か条要求（1915）\n・秘密外交：フセイン・マクマホン協定（1915）、サイクス・ピコ協定（1916）、バルフォア宣言（1917）\n・ドイツの無制限潜水艦作戦 → アメリカ参戦（1917）。ウィルソンの十四か条（1918）\n・ブレスト=リトフスク条約でロシア離脱 → キール軍港の水兵反乱 → ドイツ革命、皇帝退位 → 休戦（1918年11月）\n■ ロシア革命\n・二月（三月）革命（1917）：ペトログラードの暴動、ソヴィエト結成、ニコライ2世退位、臨時政府（ケレンスキー）\n・レーニンの四月テーゼ → 十月（十一月）革命：ボリシェヴィキが臨時政府を倒す。「平和に関する布告」「土地に関する布告」\n・憲法制定議会を解散、一党独裁。首都モスクワ。対ソ干渉戦争（シベリア出兵）、赤軍（トロツキー）、チェカ、戦時共産主義 → コミンテルン（1919）\n・新経済政策（ネップ、1921）→ ソヴィエト社会主義共和国連邦（1922）\n・スターリン：一国社会主義論、トロツキー追放、第1次五か年計画（1928、農業集団化：コルホーズ・ソフホーズ）、大粛清、スターリン憲法（1936）\n■ ヴェルサイユ体制とワシントン体制\n・パリ講和会議（1919）：民族自決（東欧に限定）。ヴェルサイユ条約：ドイツの全植民地放棄、アルザス・ロレーヌをフランスへ、ラインラント非武装化、巨額の賠償金\n・サン=ジェルマン条約（墺）、ヌイイ条約（ブルガリア）、トリアノン条約（ハンガリー）、セーヴル条約（トルコ）\n・国際連盟（1920、本部ジュネーヴ）：アメリカは上院の反対で不参加、ドイツ・ソ連は当初除外\n・ワシントン会議（1921〜22）：四か国条約（日英同盟解消）、九か国条約（中国の主権尊重）、海軍軍備制限条約\n・国際協調：ドーズ案（1924）、ロカルノ条約（1925、シュトレーゼマン）、ドイツの国際連盟加盟（1926）、不戦条約（1928、ブリアン・ケロッグ）、ヤング案\n■ 戦間期の欧米\n・イギリス：第4回選挙法改正（1918、女性参政権）、マクドナルドの労働党内閣、アイルランド自由国（1922）、ウェストミンスター憲章（1931、イギリス連邦）\n・フランス：ルール占領（1923、ポワンカレ）→ 失敗\n・ドイツ：ヴァイマル共和国（エーベルト大統領、ヴァイマル憲法：社会権）、スパルタクス団の蜂起、インフレーション → シュトレーゼマンのレンテンマルク\n・イタリア：ムッソリーニのファシスト党、ローマ進軍（1922）、フィウメ併合、ラテラノ条約（1929、ヴァチカン市国）\n・アメリカ：「永遠の繁栄」、大量生産・大量消費（フォード）、ラジオ・映画。移民法（1924）、禁酒法、クー=クラックス=クラン\n・東欧：ポーランド（ピウスツキ）、ハンガリー（ホルティ）などで権威主義体制\n■ アジア・アフリカの民族運動\n・朝鮮：三・一独立運動（1919）→ 大韓民国臨時政府（上海）、日本は「文化政治」へ\n・中国：新文化運動（陳独秀『新青年』、胡適の白話運動、魯迅『狂人日記』、李大釗）→ 五・四運動（1919）→ 中国国民党（1919）・中国共産党（1921、陳独秀）→ 第1次国共合作（1924、「連ソ・容共・扶助工農」）→ 孫文死去、五・三〇運動 → 蔣介石の北伐（1926）→ 上海クーデタ（1927）、南京国民政府 → 張作霖爆殺 → 張学良が国民政府に合流、北伐完了（1928）\n・共産党：毛沢東が瑞金に中華ソヴィエト共和国臨時政府（1931）→ 長征 → 延安\n・インド：ローラット法（1919）→ アムリットサール事件 → ガンディーの非暴力・不服従運動 → ネルーらのプールナ=スワラージ（1929、ラホール大会）→ 塩の行進（1930）→ 英印円卓会議 → 1935年インド統治法。ジンナーのムスリム連盟\n・トルコ：ムスタファ=ケマルがアンカラに大国民議会 → ギリシア軍を撃退 → スルタン制廃止（1922）→ ローザンヌ条約（1923）→ トルコ共和国（1923）、カリフ制廃止、女性参政権、文字改革（ローマ字）\n・西アジア：エジプト王国（1922、ワフド党）、イラン（レザー=ハーンのパフレヴィー朝、1925）、サウジアラビア王国（イブン=サウード、1932）、イラク王国、パレスチナ問題\n・東南アジア：インドネシア国民党（スカルノ）、ベトナム（ホー=チ=ミンのインドシナ共産党）、ビルマ（タキン党）、フィリピン独立法（1934）、タイ立憲革命（1932）",
