"note": "■ 世界恐慌（1929〜）\n・1929年10月、ニューヨーク株式市場（ウォール街）の株価大暴落 → 世界に拡大。フーヴァー=モラトリアム（1931）\n・アメリカ：フランクリン=ローズヴェルトのニューディール（全国産業復興法NIRA、農業調整法AAA、テネシー川流域開発公社TVA、ワグナー法、社会保障法）。善隣外交、ソ連承認（1933）\n・イギリス：マクドナルドの挙国一致内閣、金本位制停止、オタワ連邦会議（1932）でスターリング=ブロック\n・フランス：フラン=ブロック、人民戦線内閣（ブルム、1936）\n・ソ連は五か年計画で恐慌の影響を受けず\n■ ファシズムの台頭\n・ドイツ：ヒトラーのナチ党（国民社会主義ドイツ労働者党）→ 首相就任（1933）→ 国会議事堂放火事件、全権委任法で一党独裁 → 総統（1934）。国際連盟脱退（1933）、再軍備宣言（1935）、ラインラント進駐（1936）、ユダヤ人迫害（ニュルンベルク法）、アウトバーン\n・イタリア：エチオピア侵攻（1935〜36）→ 国際連盟の経済制裁は効果なし\n・日本：満洲事変（1931、柳条湖事件）→ 満洲国（1932、溥儀）→ リットン調査団 → 国際連盟脱退（1933）\n・スペイン内戦（1936〜39）：人民戦線政府 vs フランコ（独伊が支援）。英仏は不干渉政策、国際義勇軍（ヘミングウェー）、ピカソ「ゲルニカ」\n・枢軸の形成：ベルリン=ローマ枢軸（1936）、日独防共協定（1936）→ 日独伊三国防共協定（1937）。コミンテルンは人民戦線戦術（1935）\n・中国：西安事件（1936、張学良が蔣介石を監禁）→ 盧溝橋事件（1937）→ 日中戦争、第2次国共合作、南京事件。国民政府は重慶へ、汪兆銘の親日政権\n■ 第二次世界大戦\n・オーストリア併合（1938）→ ミュンヘン会談（1938、ネヴィル=チェンバレンの宥和政策、ズデーテン地方割譲）→ チェコスロヴァキア解体（1939）→ 独ソ不可侵条約（1939年8月）\n・1939年9月1日、ドイツのポーランド侵攻 → 英仏が宣戦。ソ連はポーランド東部・バルト3国・フィンランドに侵攻（ソ連＝フィンランド戦争）\n・1940年：デンマーク・ノルウェー・オランダ・ベルギー侵攻 → パリ陥落、ヴィシー政府（ペタン）、ド=ゴールの自由フランス政府（ロンドン）。イタリア参戦。チャーチル内閣、バトル=オブ=ブリテン\n・日独伊三国同盟（1940）、日ソ中立条約（1941）\n・1941年6月、独ソ戦開始。武器貸与法。大西洋憲章（1941年8月、ローズヴェルトとチャーチル）\n・1941年12月、日本の真珠湾攻撃・マレー半島上陸 → 太平洋戦争。「大東亜共栄圏」\n・転換：ミッドウェー海戦（1942）、スターリングラードの戦い（1942〜43）、イタリア降伏（1943）\n・カイロ会談（1943）、テヘラン会談（1943）→ ノルマンディー上陸作戦（1944）→ パリ解放 → ヤルタ会談（1945年2月、ソ連の対日参戦密約）→ ドイツ降伏（1945年5月）\n・ポツダム宣言（1945年7月）→ 広島・長崎に原子爆弾、ソ連の対日参戦 → 日本降伏（1945年8月）\n・ナチスのホロコースト（アウシュヴィッツ）、レジスタンス、ユーゴスラヴィアのティトー\n■ 戦後構想\n・大西洋憲章 → ダンバートン=オークス会議 → サンフランシスコ会議（1945）→ 国際連合発足（1945年10月、安全保障理事会の5常任理事国に拒否権）\n・ブレトン=ウッズ体制：国際通貨基金（IMF）・国際復興開発銀行（IBRD、世界銀行）、ドルを基軸通貨とする固定相場制。GATT（1947）\n・ニュルンベルク裁判・極東国際軍事裁判（東京裁判）",
