"short": "冷戦",
"title": "冷戦とアジア・アフリカ諸国の独立",
"note": "■ 冷戦の始まり\n・チャーチルの「鉄のカーテン」演説（1946）\n・トルーマン=ドクトリン（1947、封じ込め政策）、マーシャル=プラン（1947）⇔ コミンフォルム（1947）、チェコスロヴァキアのクーデタ（1948）、ユーゴスラヴィアのコミンフォルム除名\n・ベルリン封鎖（1948〜49）→ ドイツ連邦共和国（西独、アデナウアー）とドイツ民主共和国（東独）（1949）\n・西側：北大西洋条約機構（NATO、1949）、ANZUS・SEATO・バグダード条約機構（METO）。東側：経済相互援助会議（COMECON、1949）、ワルシャワ条約機構（1955）\n・ソ連の原爆保有（1949）→ 核軍拡競争、水爆。スプートニク1号（1957）\n■ 東アジア\n・中国：国共内戦 → 中華人民共和国（1949年10月、毛沢東主席・周恩来首相）、国民党は台湾へ。中ソ友好同盟相互援助条約（1950）\n・朝鮮：北緯38度線で分割 → 大韓民国（李承晩）・朝鮮民主主義人民共和国（金日成）（1948）→ 朝鮮戦争（1950〜53、国連軍・中国人民義勇軍）→ 板門店で休戦協定\n・日本：サンフランシスコ平和条約・日米安全保障条約（1951）\n・中国の社会主義化：大躍進（1958、人民公社）の失敗 → 劉少奇・鄧小平の調整 → プロレタリア文化大革命（1966〜、紅衛兵）。中ソ対立、中印国境紛争\n■ 平和共存と多極化\n・スターリン死去（1953）→ フルシチョフのスターリン批判（1956）→ ポーランドのポズナニ暴動、ハンガリー反ソ暴動（ナジ）\n・ジュネーヴ4巨頭会談（1955）、フルシチョフ訪米（1959）→ U2型機事件、ベルリンの壁（1961）\n・キューバ革命（1959、カストロ）→ キューバ危機（1962、ケネディ）→ 部分的核実験禁止条約（1963）、核拡散防止条約（NPT、1968）\n・ヨーロッパの統合：ECSC（1952、シューマン=プラン）→ EEC・EURATOM（1958）→ EC（1967）。フランスのド=ゴールはNATO軍事機構から脱退（1966）、中国承認\n・ソ連：ブレジネフ → プラハの春（1968、ドプチェク）をワルシャワ条約機構軍が弾圧\n・デタント：西独ブラントの東方外交、東西ドイツの国連加盟（1973）、SALT I、全欧安全保障協力会議（ヘルシンキ宣言、1975）\n・アメリカ：マッカーシズム、公民権運動（キング牧師、ワシントン大行進1963）、公民権法（1964、ジョンソン）、「偉大な社会」\n■ アジア・アフリカの独立\n・インド・パキスタン分離独立（1947）、ガンディー暗殺（1948）、ネルー首相。カシミール問題、のちバングラデシュ独立（1971）\n・スリランカ（セイロン）、ビルマ（アウン=サン）独立\n・インドネシア独立（スカルノ、1945宣言、1949承認）→ 九・三〇事件（1965）→ スハルト\n・フィリピン独立（1946）、マラヤ連邦（1957）→ マレーシア（1963）→ シンガポール分離（1965、リー=クアンユー）\n・ベトナム：ベトナム民主共和国（1945、ホー=チ=ミン）→ インドシナ戦争 → ディエンビエンフーの戦い（1954）→ ジュネーヴ休戦協定（北緯17度線）→ ベトナム共和国（ゴ=ディン=ディエム）→ 南ベトナム解放民族戦線（1960）→ トンキン湾事件・北爆（1965）→ ベトナム（パリ）和平協定（1973）→ サイゴン陥落（1975）→ ベトナム社会主義共和国（1976）。カンボジアのポル=ポト政権\n・第三勢力：ネルー・周恩来の平和五原則（1954）→ アジア=アフリカ会議（バンドン会議、1955、平和十原則）→ 第1回非同盟諸国首脳会議（1961、ベオグラード、ティトー）\n・アフリカ：ガーナ独立（1957、エンクルマ）→「アフリカの年」（1960、17か国）→ アフリカ統一機構（OAU、1963）。コンゴ動乱、アルジェリア独立（1962）、南アフリカのアパルトヘイト\n・中東：イスラエル建国（1948）→ 第1次中東戦争 → パレスチナ難民。エジプト革命（1952、ナギブ・ナセル）→ スエズ運河国有化 → 第2次中東戦争（スエズ戦争、1956）→ 第3次中東戦争（1967、イスラエルがシナイ半島・ガザ・ヨルダン川西岸・ゴラン高原を占領）→ PLO（アラファト）→ 第4次中東戦争（1973）→ 石油戦略\n・イラン：モサデグの石油国有化（1951）→ クーデタで失脚 → パフレヴィー2世の白色革命\n・ラテンアメリカ：アルゼンチンのペロン、米州機構（OAS、1948）、チリのアジェンデ政権 → ピノチェトのクーデタ（1973）",
